```json
{
  "data_catalog": [
    {
      "dataset": "cash_weekly",
      "description": "موجودی نقد هفتگی شرکت",
      "dimensions": [
        "week"
      ],
      "measures": [
        "cash_m"
      ]
    },
    {
      "dataset": "supplier_payables",
