        "category",
        "month"
      ],
      "measures": [
        "revenue_m",
        "cogs_m",
        "waste_m"
      ]
    },
    {
      "dataset": "cash_weekly",
      "description": "موجودی نقد هفتگی شرکت",
      "dimensions": [
        "week"
      ],
      "measures": [
